// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length <= 10);
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c)); // avoid potential self-call issues

        // Simulate call to transferFrom for each recipient to check if it would revert
        bool anyRevert = false;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint256 i = 0; i < tos.length; i++) {
            (bool success, ) = caddress.call(abi.encodeWithSelector(id, from, tos[i], v));
            if (!success) {
                anyRevert = true;
                break;
            }
        }

        // Now call the contract's transfer function
        (bool txSuccess, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, tos, v));

        // Rule: if any individual call would fail, the whole transfer should revert; otherwise it should succeed
        if (anyRevert) {
            assertTrue(!txSuccess, "Should revert when any transferFrom call fails");
        } else {
            assertTrue(txSuccess, "Should succeed when all transferFrom calls pass");
        }
    }
}

